    try { slider.focus(); } catch (e) {}
    reactKeyDown(slider, 'Home') || fireKey(slider, 'Home');
    await sleep(70);
    for (var i = min; i < want; i++) { reactKeyDown(slider, 'ArrowRight') || fireKey(slider, 'ArrowRight'); await sleep(45); }
